  tournamentId,
  eventId,
}: {
  token: string;
  tournamentId: string;
  eventId: string;
}) {
  const queryClient = useQueryClient();
  const query = useQuery(
    ["shareResultsEvent", token, tournamentId, eventId],
    () => getShareResultsEvent(token, tournamentId, eventId),
    {
      retry: false,
      onError: (error) => {
        if (error instanceof HttpError && error.status === 404) {
          void queryClient.invalidateQueries(["shareResultsView", token]);
        }
      },
    },
  );

  const event = query.data;

  return (
    <ResultsEventCard
      event={event}
      errorMessage={query.isError ? "Unable to load this event." : undefined}
    >
      {(loadedEvent) => (
        <ResultsMatchesTable
          matches={loadedEvent.results}
          renderOpponentName={(opponent) => opponent.name}
          renderVideo={(_opponent, match) => <ShareVideoAnchors match={match} />}
        />
      )}
    </ResultsEventCard>
  );
